class MapSum {
    struct Node {
        Node* children[26] = {};
        int sum = 0;
    };
    Node* root;
    unordered_map<string, int> vals;
public:
    MapSum() {
        root = new Node();
    }

    void insert(string key, int val) {
        int delta = val - vals[key];
        vals[key] = val;
        Node* cur = root;
        cur->sum += delta;
        for (char c : key) {
            int idx = c - 'a';
            if (!cur->children[idx]) cur->children[idx] = new Node();
            cur = cur->children[idx];
            cur->sum += delta;
        }
    }

    int sum(string prefix) {
        Node* cur = root;
        for (char c : prefix) {
            int idx = c - 'a';
            if (!cur->children[idx]) return 0;
            cur = cur->children[idx];
        }
        return cur->sum;
    }
};
